def simple_calculator(num1, operator, num2):
    # Initialize a variable to store the result.
    result = 0 
    # Check the operator to perform the correct calculation.
    if operator == '+':
        result = num1 + num2
    elif operator == '-':
        result = num1 - num2
    elif operator == '*':
        result = num1 * num2
    elif operator == '/':
        # Handle the special case of division by zero.
        if num2 == 0:
            # Return 'Error' for invalid division.
            return 'Error'
        result = num1 / num2
    else:
        # For any unsupported operator, return 'Error'.
        return 'Error'
    # The calculated result is returned.
    return result

