def merge_dictionaries(dict1, dict2):
    # Initialize a new dictionary to store the merged result.
    merged_dict = {}

    # Iterate through the first dictionary and add its items.
    for key, value in dict1.items():
        merged_dict[key] = value

    # Iterate through the second dictionary.
    for key, value in dict2.items():
        # Overwrite existing keys or add new ones from dict2.
        merged_dict[key] = value
    # Return the final merged dictionary.
    return merged_dict

# Example usage to demonstrate the function.
dict_a = {'a': 1, 'b': 2}
dict_b = {'b': 3, 'c': 4}
# Perform the merge operation.
result_dict = merge_dictionaries(dict_a, dict_b)
# Print the outcome of the merge.
print(result_dict)

dict_x = {'name': 'Alice', 'age': 30}
dict_y = {'age': 31, 'city': 'New York'}
# Another example to confirm the merge logic.
result_dict_2 = merge_dictionaries(dict_x, dict_y)
# Display the second result.
print(result_dict_2)

